function f = HS50_f(x)
f = (x(1) - x(2)).^2 + (x(2) - x(3)).^2 + (x(3) - x(4)).^4 + (x(4) - x(5)).^2;
end

function g = HS50_g(x)
g = zeros(5, 1);
g(1) = 2*x(1) - 2*x(2);
g(2) = -2*x(1) + 4*x(2) - 2*x(3);
g(3) = -2*x(2) + 2*x(3) + 4*(x(3) - x(4)).^3;
g(4) = 2*x(4) - 2*x(5) - 4*(x(3) - x(4)).^3;
g(5) = -2*x(4) + 2*x(5);
end

function c = HS50_c(x)
c = zeros(3, 1);
c(1) = x(1) + 2*x(2) + 3*x(3) - 6;
c(2) = x(2) + 2*x(3) + 3*x(4) - 6;
c(3) = x(3) + 2*x(4) + 3*x(5) - 6;
end

function J = HS50_J(x)
